insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('user-media','user-media',false,2097152,array['image/jpeg','image/png','image/webp']) on conflict do nothing;
create policy own_media_read on storage.objects for select to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy own_media_insert on storage.objects for insert to authenticated with check(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text and (storage.foldername(name))[2] in ('avatars','rewards') and not exists(select 1 from public.profiles where user_id=(select auth.uid()) and deletion_requested_at is not null));
create policy own_media_delete on storage.objects for delete to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy own_media_update on storage.objects for update to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text and (storage.foldername(name))[2] in ('avatars','rewards') and not exists(select 1 from public.profiles where user_id=(select auth.uid()) and deletion_requested_at is not null));
